func getPrimaryColorOrDefault(color string) string {
	if color == "" {
		return "#8040BF"
	}
	return color
}

func getSecondaryColorOrDefault(color string) string {
	if color == "" {
		return "#8040BF"
	}
	return color
}

// Helper functions for gradient parsing
func getGradientColor1(gradient string) string {
	if gradient == "" {
		return "#667eea"
	}
	// Parse "linear-gradient(135deg, #667eea, #764ba2)" to get first color
	start := strings.Index(gradient, ", ")
	if start == -1 {
		return "#667eea"
	}
	start += 2 // skip ", "
	end := strings.Index(gradient[start:], ",")
	if end == -1 {
		return "#667eea"
	}
	color := strings.TrimSpace(gradient[start : start+end])
	return color
}

func getGradientColor2(gradient string) string {
	if gradient == "" {
		return "#764ba2"
	}
	// Parse "linear-gradient(135deg, #667eea, #764ba2)" to get second color
	start := strings.LastIndex(gradient, ", ")
	if start == -1 {
		return "#764ba2"
	}
	start += 2 // skip ", "
	end := strings.Index(gradient[start:], ")")
	if end == -1 {
		return "#764ba2"
	}
	color := strings.TrimSpace(gradient[start : start+end])
	return color
}

func getGradientDirection(gradient string) string {
	if gradient == "" {
		return "135deg"
	}
	// Parse "linear-gradient(135deg, #667eea, #764ba2)" to get direction
	start := strings.Index(gradient, "(")
	if start == -1 {
		return "135deg"
	}
	start++ // skip "("
	end := strings.Index(gradient[start:], ",")
	if end == -1 {
		return "135deg"
	}
	direction := strings.TrimSpace(gradient[start : start+end])
	return direction
}

func getGradientPreviewStyle(gradient string) string {
	if gradient == "" {
		return "background: linear-gradient(135deg, #667eea, #764ba2);"
	}
	return "background: " + gradient + ";"
}

func getFontStyle(font string) string {
	if font == "" {
		return ""
	}
	return "font-family: '" + font + "', ui-sans-serif, system-ui, sans-serif;"
}

